import sys

s = input()
vowels = "AEIOUYaeiouy"
f1, f2 = 1, 1

res = []
for char in s:
    if char.isalpha():
        shift = f1 % 26
        if char in vowels:
            # Shift backward
            if char.islower():
                new_c = chr((ord(char) - ord('a') - shift) % 26 + ord('a'))
            else:
                new_c = chr((ord(char) - ord('A') - shift) % 26 + ord('A'))
        else:
            # Shift forward
            if char.islower():
                new_c = chr((ord(char) - ord('a') + shift) % 26 + ord('a'))
            else:
                new_c = chr((ord(char) - ord('A') + shift) % 26 + ord('A'))
        res.append(new_c)
    else:
        # Non-alphabetical characters stay the same
        res.append(char)

    # Next Fibonacci number
    f1, f2 = f2, f1 + f2

print("".join(res))
